#include <limits.h>
#include <stddef.h>
#include <stdio.h>

struct Item {
    const char *name;
    int quantity;
    int unit_price;
};

static int item_value(const struct Item *item, long long *value_out)
{
    if (item == NULL || value_out == NULL || item->name == NULL ||
        item->quantity < 0 || item->unit_price < 0) {
        return 0;
    }
    if (item->quantity != 0 &&
        (long long)item->unit_price > LLONG_MAX / (long long)item->quantity) {
        return 0;
    }
    *value_out = (long long)item->quantity * (long long)item->unit_price;
    return 1;
}

static int stock_total(const struct Item items[], size_t count,
                       long long *total_out)
{
    size_t i;
    long long total = 0;
    if (total_out == NULL || (count > 0U && items == NULL)) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        long long line_value;
        if (!item_value(&items[i], &line_value) ||
            line_value > LLONG_MAX - total) {
            return 0;
        }
        total += line_value;
    }
    *total_out = total;
    return 1;
}

int main(void)
{
    const struct Item items[] = {
        {"Notebook", 3, 40}, {"Pen", 5, 10}, {"Folder", 2, 25}
    };
    long long total;
    if (!stock_total(items, sizeof items / sizeof items[0], &total)) {
        fputs("cannot calculate stock total\n", stderr);
        return 1;
    }
    printf("Stock value: %lld\n", total);
    return 0;
}

#include <limits.h>
#include <stddef.h>
#include <stdio.h>

struct Student {
    const char *name;
    int score;
};

enum SummaryStatus {
    SUMMARY_INVALID = 0,
    SUMMARY_EMPTY = 1,
    SUMMARY_OK = 2
};

struct Summary {
    size_t passed;
    int highest;
    long long total;
};

static enum SummaryStatus summarize(const struct Student students[],
                                    size_t count, struct Summary *out)
{
    size_t i;
    struct Summary result = {0U, 0, 0};
    if (out == NULL || (count > 0U && students == NULL)) {
        return SUMMARY_INVALID;
    }
    if (count == 0U) {
        *out = result;
        return SUMMARY_EMPTY;
    }
    for (i = 0U; i < count; ++i) {
        const struct Student *student = &students[i];
        if (student->name == NULL || student->score < 0 || student->score > 100) {
            return SUMMARY_INVALID;
        }
        if ((long long)student->score > LLONG_MAX - result.total) {
            return SUMMARY_INVALID;
        }
        result.total += (long long)student->score;
        if (student->score >= 50) {
            ++result.passed;
        }
        if (i == 0U || student->score > result.highest) {
            result.highest = student->score;
        }
    }
    *out = result;
    return SUMMARY_OK;
}

int main(void)
{
    const struct Student students[] = {
        {"Asha", 82}, {"Ravi", 47}, {"Mina", 65}, {"Dev", 50}
    };
    const size_t count = sizeof students / sizeof students[0];
    struct Summary summary;
    enum SummaryStatus status = summarize(students, count, &summary);
    if (status == SUMMARY_INVALID) {
        fputs("invalid student data\n", stderr);
        return 1;
    }
    if (status == SUMMARY_EMPTY) {
        puts("No student records");
        return 0;
    }
    printf("Average: %.2f\n", (double)summary.total / (double)count);
    printf("Passed: %zu\n", summary.passed);
    printf("Highest: %d\n", summary.highest);
    return 0;
}
